        "body": "### 第1题｜单选\n题目：透雕为什么会让龙看起来更有穿行感？\nA. 因为把部分石料镂空\nB. 因为涂了会发光的颜料\nC. 因为龙柱会转动\nD. 因为石头是软的\n正确答案：A\n解释：正文说透雕会镂去部分石料，产生空隙和层次。\n### 第2题｜单选\n题目：安顺文庙在哪一年进入第五批全国重点文物保护单位？\nA. 1394年\nB. 1433年\nC. 2001年\nD. 2024年\n正确答案：C\n解释：正文写安顺文庙2001年进入第五批全国重点文物保护单位。\n### 第3题｜判断\n题目：正文已经确定龙柱的准确雕成年代。\nA. 正确\nB. 错误\n正确答案：B\n解释：正文说龙柱具体雕成年代缺少直接史料，仍需人工核验。"
