        "body": "### 第1题｜单选\n题目：关岭生物群常见研究对象不包括哪一类？\nA. 海生爬行动物\nB. 鱼类\nC. 海百合\nD. 现代家猫\n正确答案：D\n解释：正文列出海生爬行动物、鱼类、海百合等，没有现代家猫。\n### 第2题｜单选\n题目：为什么不能把鱼龙、海龙、鳍龙都叫作“海里的恐龙”？\nA. 因为它们是海生爬行动物，不应统称为恐龙\nB. 因为它们都是植物\nC. 因为它们生活在现代城市\nD. 因为它们没有化石\n正确答案：A\n解释：正文明确说明这些是海生爬行动物，不应统称为“海里的恐龙”。\n### 第3题｜判断\n题目：在山里发现海洋动物化石，表示这些动物生活在今天的高山湖泊里。\nA. 正确\nB. 错误\n正确答案：B\n解释：正文说这记录的是古代海洋环境，不是今天高山湖泊里的生活场景。"
