        "body": "“被贬”意味着他离开原来的官场位置，来到陌生山地，生活秩序被打乱。驿丞，是管理驿站的小官。龙场的经历，让王阳明在生活、思考和讲学中重新追问：书本上知道的道理，到了真实困境里还算不算数？贵州官方文化资料把龙场视为阳明心学形成过程中的关键地点，“龙场悟道”和“知行合一”也是修文重要的文化线索。"
