        "body": "“知行合一”不能简单解释为“想到就马上做”。儿童可以先这样理解：真正明白一件该做的事，会在行动中表现出来；行动也会检验自己是否真的理解。比如，“知道要爱护文物”不只是在答题时选对答案，还包括现场不触摸、不刻画，并提醒同行者遵守规则。王阳明后来的讲学活动还涉及龙冈书院以及贵州其他地点。思想形成有过程，不能写成某一夜突然想通全部哲学的神话。"
