export const articleByTopic=(topic:string)=>NOTION_ARTICLES.find(article=>article.topic===topic);
export function questionsFromArticle(article:NotionArticle|undefined){
  const body=article?.sections.find(section=>section.heading==="听完挑战")?.body||"";
  return body.split(/(?=### 第\d+题)/).map((block,index)=>{
    const prompt=block.match(/题目：([^\n]+)/)?.[1]?.trim();
    const options=[...block.matchAll(/^[A-D]\.\s*([^\n]+)/gm)].map(match=>match[1].trim());
    const answer=block.match(/正确答案：([A-D])/)?.[1];
    const explanation=block.match(/解释：([^\n]+)/)?.[1]?.trim().replace("这条信息来自文章的事实核验表：","文章内容说明：");
    if(!prompt||options.length<2||!answer||!explanation)return null;
    return {id:`article-${index+1}`,type:block.includes("｜判断")?"boolean" as const:"single" as const,prompt,options,correct:"ABCD".indexOf(answer),explanation};
  }).filter(Boolean);
}
